def bellman_ford(graph, source, num_vertices):
    # Initialize distances
    INF = float('inf')
    distances = {node: INF for node in range(num_vertices)}
    distances[source] = 0

    # Relax edges num_vertices - 1 times
    for _ in range(num_vertices - 1):
        updated = False
        for u, v, w in graph:
            if distances[u] + w < distances[v]:
                distances[v] = distances[u] + w
                updated = True
        if not updated:
            break  # Early exit if no more updates

    # Check for negative weight cycles
    for u, v, w in graph:
        if distances[u] + w < distances[v]:
            return "Negative weight cycle detected"

    return distances

