def replace_question_marks(s: str) -> str:
    result = []
    for c in s:
        if c == '?':
            prev = result[-1] if result else None
            for i in range(26):
                new_char = chr(ord('a') + i)
                if prev is None or new_char != prev:
                    result.append(new_char)
                    break
        else:
            result.append(c)
    return ''.join(result)

