def can_be_non_decreasing(nums):
    n = len(nums)
    if n <= 1:
        return True

    # Find the first index where the array is not non-decreasing
    i = 0
    while i < n - 1 and nums[i] <= nums[i + 1]:
        i += 1

    if i == n - 1:
        return True  # Already non-decreasing

    # Check if we can fix the array by modifying one element
    # Option 1: Change nums[i] to nums[i + 1]
    if nums[i - 1] <= nums[i + 1]:
        return True
    # Option 2: Change nums[i + 1] to nums[i]
    elif nums[i] <= nums[i + 2]:
        return True
    else:
        return False

