def minimum_number_of_trucks(n, m, package_weights, truck_capacities):
    total = sum(package_weights)
    if total == 0:
        return 0
    if total > sum(truck_capacities):
        return -1
    sorted_trucks = sorted(truck_capacities)
    sorted_packages = sorted(package_weights)
    remaining = sorted_trucks.copy()
    for weight in sorted_packages:
        for i in range(len(remaining)):
