def find_majority_element(n: int, nums: List[int]) -> int:
    if n == 0:
        return -1
    count = 0
    candidate = None
    for num in nums:
        if count == 0:
            candidate = num
            count = 1
        else:
            if num == candidate:
                count += 1
            else:
                count -= 1
    if nums.count(candidate) > n // 2:
        return candidate
    else:
        return -1

