def longest_stable_subarray(N: int, K: int, A: List[int]) -> int:
    left = 0
    max_len = 0
    current_min = A[0]
    current_max = A[0]

    for right in range(1, N):
        # Update current_min and current_max
        if A[right] < current_min:
            current_min = A[right]
        if A[right] > current_max:
            current_max = A[right]

        # Check if current window is valid
        while current_max - current_min > K:
            # Move left pointer and update current_min and current_max
            if A[left] == current_min:
                current_min = A[left + 1]
            if A[left] == current_max:
                current_max = A[left + 1]
            left += 1

        # Update max length
        current_length = right - left + 1
        if current_length > max_len:
            max_len = current_length

    return max_len

