def longest_subarray_with_two_distinct(nums):
    left = 0
    max_len = 0
    freq = {}
    distinct = 0

    for right in range(len(nums)):
        num = nums[right]
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1
            distinct += 1

        # If we have more than two distinct numbers, move left pointer
        while distinct > 2:
            left_num = nums[left]
            freq[left_num] -= 1
            if freq[left_num] == 0:
                distinct -= 1
            left += 1

        # Update the maximum length if current window is valid
        current_len = right - left + 1
        if current_len > max_len:
            max_len = current_len

    return max_len

