def find_minimum_spanning_tree(n, m, edges):
    if n == 1:
        return 0
    if m == 0:
        return -1

    edges.sort(key=lambda x: x[2])

    parent = list(range(n + 1))  # 1-based indexing
    rank = [1] * (n + 1)

    total = 0
    count = 0

    for u, v, w in edges:
        root_u = find(u, parent, rank)
        root_v = find(v, parent, rank)
        if root_u != root_v:
            total += w
            count += 1
            if count == n - 1:
                break
            # Union by rank
            if rank[root_u] > rank[root_v]:
                parent[root_v] = root_u
            else:
                parent[root_u] = root_v
                if rank[root_u] == rank[root_v]:
                    rank[root_v] += 1

    return total if count == n - 1 else -1

def find(u, parent, rank):
    if parent[u] != u:
        parent[u] = find(parent[u], parent, rank)
    return parent[u]

