def calculate_student_averages(words):
    student_scores = {}
    for word in words:
        parts = word.split(':')
        student_id = parts[0]
        score = int(parts[1])
        if student_id in student_scores:
            student_scores[student_id][0] += score
            student_scores[student_id][1] += 1
        else:
            student_scores[student_id] = [score, 1]

    averages = []
    for student_id in student_scores:
        total, count = student_scores[student_id]
        average = total / count
        rounded_avg = round(average, 2)
        averages.append((student_id, rounded_avg))

    averages.sort(key=lambda x: x[0])
    result = []
    for student_id, avg in averages:
        result.append(f"{student_id}:{avg:.2f}")
    return result

