def is_well_formed_bracket_sequence(S: str) -> str:
    stack = []
    closing_to_opening = {')': '(', '}': '{', ']': '['}
    for char in S:
        if char in closing_to_opening.values():
            stack.append(char)
        elif char in closing_to_opening:
            if not stack:
                return "NO"
            top = stack.pop()
            if top != closing_to_opening[char]:
                return "NO"
    return "YES" if not stack else "NO"

