def sum_of_subarray_minima():
    import sys
    nums = list(map(int, sys.stdin.readline().split()))
    k = int(sys.stdin.readline())
    n = len(nums)

    if k == 0:
        print(0)
        return

    left = [0] * n
    stack = []
    for i in range(n):
        while stack and nums[stack[-1]] >= nums[i]:
            stack.pop()
        if stack:
            left[i] = stack[-1]
        else:
            left[i] = -1
        stack.append(i)

    right = [0] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and nums[stack[-1]] > nums[i]:
            stack.pop()
        if stack:
            right[i] = stack[-1]
        else:
            right[i] = n
        stack.append(i)

    total = 0
    for i in range(n):
        count = right[i] - left[i] - 1
        if count >= k:
            total += nums[i] * count

    print(total)

