class Library:
    def __init__(self):
        self.books = {}

    def add_book(self, title, author, year, copies=1):
        if title in self.books:
            self.books['copies'] += copies
        else:
            self.books = {
                'title': title,
                'author': author,
                'year': year,
                'copies': copies
            }

    def borrow_book(self, title):
        if title in self.books:
            if self.books['copies'] > 0:
                self.books['copies'] -= 1
            else:
                raise ValueError("Book not available or out of stock.")
        else:
            raise ValueError("Book not available or out of stock.")

    def return_book(self, title):
        if title in self.books:
            self.books['copies'] += 1
        else:
            raise ValueError("Book does not exist in the library.")

    def list_books(self):
        available_books = []
        for title in self.books:
            if self.books['copies'] > 0:
                available_books.append(title)
        return available_books

