from typing import List, Tuple

def determine_capital(N: int, M: int, A: int, B: int, residents: List[int], roads: List[Tuple[int, int]]) -> int:
    # Build adjacency list
    adj = [[] for _ in range(N + 1)]
    for u, v in roads:
        adj[u].append(v)
        adj[v].append(u)

    # BFS to compute distances from A
    dist_A = [-1] * (N + 1)
    queue = deque()
    queue.append(A)
    dist_A[A] = 0
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist_A[v] == -1:
                dist_A[v] = dist_A[u] + 1
                queue.append(v)

    # BFS to compute distances from B
    dist_B = [-1] * (N + 1)
    queue = deque()
    queue.append(B)
    dist_B[B] = 0
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist_B[v] == -1:
                dist_B[v] = dist_B[u] + 1
                queue.append(v)

    # Compute max distance for A and B
    max_dist_A = 0
    for i in range(1, N + 1):
        if dist_A[i] == -1:
            return -1  # Assuming the graph is connected as per problem context
        if dist_A[i] > max_dist_A:
            max_dist_A = dist_A[i]

    max_dist_B = 0
    for i in range(1, N + 1):
        if dist_B[i] == -1:
            return -1
        if dist_B[i] > max_dist_B:
            max_dist_B = dist_B[i]

    # Determine the result
    if max_dist_A < max_dist_B:
        return A
    elif max_dist_B < max_dist_A:
        return B
    else:
        return min(A, B)

