def four_sum_count(arr, target):
    arr.sort()
    n = len(arr)
    count = 0
    for i in range(n - 3):
        for j in range(i + 1, n - 2):
            remaining = target - arr[i] - arr[j]
            left = j + 1
            right = n - 1
            while left < right:
                current_sum = arr[left] + arr[right]
                if current_sum == remaining:
                    count += 1
                    left += 1
                    right -= 1
                elif current_sum < remaining:
                    left += 1
                else:
                    right -= 1
    return count

