def arrange_books(n: int, g: int, counts: List[int]) -> str:
    if g == 1:
        if n == 1:
            return "Possible\n1"
        else:
            return "Not possible"

    max_count = max(counts)
    if max_count > (n + 1) // 2:
        return "Not possible"

    # Generate the sequence
    genres = [chr(ord('a') + i) for i in range(g)]
    result = []
    current_counts = counts.copy()

    while True:
        # Find the genre with the maximum remaining count
        max_count = -1
        best_genre = -1
        for i in range(g):
            if current_counts[i] > max_count:
                max_count = current_counts[i]
                best_genre = i

        if best_genre == -1:
            break  # All counts are zero

        result.append(genres[best_genre])
        current_counts[best_genre] -= 1

        if all(c == 0 for c in current_counts):
            break

    return f"Possible\n{' '.join(result)}"

