def sum_of_primes(n):
    if n < 2:
        return 0
    sieve = [True] * (n + 1)
    sieve[0], sieve[1] = False, False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i*i : n+1 : i] = [False] * len(sieve[i*i : n+1 : i])
    return sum(i for i, is_prime in enumerate(sieve) if is_prime)

