def validate_isbn_10(isbn: str) -> bool:
    if len(isbn) != 10:
        return False
    total = 0
    for i in range(10):
        c = isbn[i]
        if c.isdigit():
            digit = int(c)
            weight = 10 - i
            total += digit * weight
        elif c == 'X':
            if i == 9:
                total += 10
            else:
                return False
        else:
            return False
    return total % 11 == 0

