from typing import List

def find_hamiltonian_path(n: int, graph: List[List[int]]) -> str:
    def backtrack(current, visited, path):
        if len(path) == n:
            return True
        for neighbor in range(n):
            if graph[current][neighbor] == 1 and not visited[neighbor]:
                visited[neighbor] = True
                path.append(neighbor)
                if backtrack(neighbor, visited, path):
                    return True
                path.pop()
                visited[neighbor] = False
        return False

    for start in range(n):
        visited = [False] * n
        visited[start] = True
        path = [start]
        if backtrack(start, visited, path):
            return "Yes"
    return "No"

