from typing import List

def stooge_sort(arr: List[int]) -> List[int]:
    def helper(start, end):
        if end - start <= 1:
            return
        if arr[start] > arr[end]:
            arr[start], arr[end] = arr[end], arr[start]
        if end - start >= 2:
            t = (end - start + 1) // 3
            helper(start, start + t - 1)
            helper(start + t, end)
            helper(start, start + t - 1)

    helper(0, len(arr) - 1)
    return arr

