    if not points:
        return []

    sorted_points = sorted(points)
    x_values = []
    for i in range(num_points):
        x = x_start + i * (x_end - x_start) / (num_points - 1)
        x_values.append(x)

    y_values = []
    for x in x_values:
        # Find the interval containing x
        low = None
        high = None
        for i in range(len(sorted_points) - 1):
            a, b = sorted_points[i], sorted_points[i+1]
            if a[0] <= x <= b[0]:
                low = a
                high = b
                break
        if low is None:
            # x is outside the range of points, return the first or last y
            if x <= sorted_points[0][0]:
                y = sorted_points[0][1]
            else:
                y = sorted_points[-1][1]
        else:
            # Perform linear interpolation
            t = (x - low[0]) / (high[0] - low[0])
            y = low[1] + t * (high[1] - low[1])
        y_values.append(y)

    return y_values

