def find_combinations(n: int, T: int):
    result = []

    def backtrack(start, path, remaining):
        if len(path) == n:
            if remaining == 0:
                result.append(path.copy())
            return
        for i in range(start, T + 1):
            if i > remaining:
                break
            path.append(i)
            backtrack(i, path, remaining - i)
            path.pop()

    backtrack(1, [], T)
    return result

