        result = max_sum_subarray(nums, N, X)
        results.append(result)
    return results

def process_booking_requests(events: dict, bookings: list) -> list:
    result = []
    for booking in bookings:
        event = booking['event']
        name = booking['name']
        number = booking['number']
        if event not in events:
            result.append({'event': event, 'name': name, 'status': 'invalid'})
        else:
            available = events[event]
            if number <= available:
                events[event] -= number
                result.append({'event': event, 'name': name, 'status': 'success'})
            else:
                result.append({'event': event, 'name': name, 'status': 'failed'})
    return result

