def most_common_substring(s, k):
    n = len(s)
    if k == 0:
        return ""
    counts = {}
    for i in range(n - k + 1):
        substr = s[i:i+k]
        counts[substr] = counts.get(substr, 0) + 1
    max_count = max(counts.values())
    candidates = [k for k, v in counts.items() if v == max_count]
    return min(candidates)

