def search_in_matrix(mat: List[List[int]], key: int) -> Optional[Tuple[int, int]]:
    if not mat or not mat[0]:
        return None
    m = len(mat)
    n = len(mat[0])
    row, col = 0, n - 1
    while row < m and col >= 0:
        current = mat[row][col]
        if current == key:
            return (row, col)
        elif current > key:
            col -= 1
        else:
            row += 1
    return None

