def count_quadruplets(nums, target):
    nums.sort()
    count = 0
    n = len(nums)
    for i in range(n - 3):
        for j in range(i + 1, n - 2):
            rem = target - nums[i] - nums[j]
            left = j + 1
            right = n - 1
            while left < right:
                current_sum = nums[left] + nums[right]
                if current_sum == rem:
                    count += 1
                    left += 1
                    right -= 1
                elif current_sum < rem:
                    left += 1
                else:
                    right -= 1
    return count

