from typing import List

def is_invertible(s: str) -> str:
    """
    Determines if the string s is invertible according to the defined rules.
    """
    n = len(s)
    if n == 0:
        return 'YES'
    if n == 1:
        return 'YES'
    if n % 2 != 0:
        return 'NO'
    for i in range(n // 2):
        if s[i] != s[n - 1 - i]:
            return 'NO'
    return 'YES'

