def count_squares_with_sum(grid, x, threshold):
    m = len(grid)
    n = len(grid[0]) if m > 0 else 0
    if x == 0 or x > m or x > n:
        return 0
    # Compute prefix sums
    prefix = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            prefix[i][j] = grid[i-1][j-1] + prefix[i-1][j] + prefix[i][j-1] - prefix[i-1][j-1]
    count = 0
    for i in range(m - x + 1):
        for j in range(n - x + 1):
            a = i + x
            b = j + x
            total = prefix[a][b] - prefix[i][b] - prefix[a][j] + prefix[i][j]
            if total > threshold:
                count += 1
    return count

