def is_hamiltonian_cycle(n: int, edges: List[Tuple[int, int]]) -> str:
    if n == 1:
        return "possible"
    if n == 2:
        return "possible" if len(edges) == 1 else "impossible"

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check if the graph is connected
    visited = [False] * (n + 1)
    queue = [1]
    visited[1] = True
    count = 1

    while queue:
        u = queue.pop(0)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                count += 1
                queue.append(v)

    if count != n:
        return "impossible"

    # Check if all nodes have even degree
    for i in range(1, n + 1):
        if len(adj[i]) % 2 != 0:
            return "impossible"

    # Check if the graph is a single cycle
    # Find a starting node with degree 2
    start = None
    for i in range(1, n + 1):
        if len(adj[i]) == 2:
            start = i
            break

    if start is None:
        return "impossible"

    # Traverse the cycle
    current = start
    prev = None
    visited_nodes = set()
    visited_nodes.add(current)

    for _ in range(n - 1):
        next_node = None
        for neighbor in adj[current]:
            if neighbor == prev:
                continue
            if neighbor not in visited_nodes:
                next_node = neighbor
                break
        if next_node is None:
            return "impossible"
        prev = current
        current = next_node
        visited_nodes.add(current)

    return "possible"

