from typing import List

def common_activities(n: int, activities_list: List[str]) -> str:
    if n == 0:
        return "No common activities"

    all_activities = set()
    for activities in activities_list:
        all_activities.update(activities.split())

    if not all_activities:
        return "No common activities"

    common = all_activities.copy()
    for activities in activities_list:
        current = set(activities.split())
        common = common.intersection(current)
        if not common:
            break

    if not common:
        return "No common activities"

    sorted_common = sorted(common)
    return ' '.join(sorted_common)

