from collections import deque

def max_problems_solved(T, cases):
    results = []
    for case in cases:
        P, D, deps = case
        if P == 0:
            results.append(0)
            continue
        # Build adjacency list and in-degree array
        adj = [[] for _ in range(P + 1)]
        in_degree = [0] * (P + 1)
        for X, Y in deps:
            adj[X].append(Y)
            in_degree[Y] += 1
        # Kahn's algorithm to find topological order
        queue = deque()
        for i in range(1, P + 1):
            if in_degree[i] == 0:
                queue.append(i)
        count = 0
        while queue:
            u = queue.popleft()
            count += 1
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)
        if count == P:
            results.append(P)
        else:
            results.append(-1)
    return results

