from typing import List, Tuple

def process_bytearrays(string_length_pairs: List[Tuple[str, int]], final_length: int) -> str:
    if final_length == 0:
        return ''
    total = sum(len(s) for s, l in string_length_pairs)
    if total >= final_length:
        combined = ''.join(s for s, l in string_length_pairs)
        return combined[:final_length]
    else:
        combined = ''.join(s for s, l in string_length_pairs)
        padding = final_length - total
        return combined + '\x00' * padding

