from typing import List

class FenwickTree:
    def __init__(self, arr: List[int]) -> None:
        self.n = len(arr)
        self.tree = [0] * (self.n + 1)  # 1-based indexing
        for i in range(self.n):
            self._add(i, arr[i])

    def _add(self, idx: int, delta: int) -> None:
        i = idx + 1  # Convert to 1-based index
        while i <= self.n:
            self.tree[i] += delta
            i += i & -i

    def update(self, idx: int, value: int) -> None:
        current = self._get(idx)
        delta = value - current
        self._add(idx, delta)

    def _get(self, idx: int) -> int:
        res = 0
        i = idx + 1  # Convert to 1-based index
        while i > 0:
            res += self.tree[i]
            i -= i & -i
        return res

    def query(self, idx: int) -> int:
        return self._get(idx)

