def get_advanced_histogram(input_list: list) -> dict:
    if not input_list:
        return {}

    counts = {}
    positions = {}

    for index, num in enumerate(input_list):
        if num in counts:
            counts[num] += 1
            if num in positions:
                positions[num].append(index)
            else:
                positions[num] = [index]
        else:
            counts[num] = 1
            positions[num] = [index]

    result = {}
    for num in counts:
        freq = counts[num]
        pos = positions[num]
        proportion = freq / len(input_list)
        result[num] = {
            'frequency': freq,
            'position': pos,
            'proportion': proportion
        }

    return result
