    # Using Core Aten IR to add the tensors
    result_aten = torch.add(tensor_a, tensor_b)

    # Using Prims IR to manually handle type promotion and broadcasting
    # Determine the common data type
    if tensor_a.dtype == tensor_b.dtype:
        common_dtype = tensor_a.dtype
    else:
        # Determine the common data type based on PyTorch's promotion rules
        if tensor_a.dtype.is_floating_point and tensor_b.dtype.is_floating_point:
            common_dtype = torch.float32
