def trap_water(arr):
    if not arr:
        return 0
    n = len(arr)
    left_max = [0] * n
    for i in range(1, n):
        left_max[i] = max(left_max[i-1], arr[i-1])
    right_max = [0] * n
    for i in range(n-2, -1, -1):
        right_max[i] = max(right_max[i+1], arr[i+1])
    total = 0
    for i in range(n):
        water = min(left_max[i], right_max[i]) - arr[i]
        if water > 0:
            total += water
    return total

