def subsequence_sum_exists(nums: List[int], target: int) -> bool:
    if target == 0:
        return True
    possible_sums = {0}
    for num in nums:
        temp = set()
        for s in possible_sums:
            new_sum = s + num
            if new_sum == target:
                return True
            if new_sum != target:
                temp.add(new_sum)
        possible_sums.update(temp)
    return target in possible_sums

