    for i in range(rows):
        for j in range(cols-1, -1, -1):
            if grid[i][j] == 1:
                if i == 0 or j == cols-1:
                    right[i][j] = 1
                else:
                    right[i][j] = right[i][j+1] + 1

    # Compute top array
