from typing import List

def can_reach(n: int, m: int, grid: List[str], sx: int, sy: int, tx: int, ty: int) -> str:
    if sx == tx and sy == ty:
        return "yes"

    visited = [[False for _ in range(m)] for _ in range(n)]
    queue = deque()
    queue.append((sx, sy))
    visited[sx][sy] = True

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            new_x = x + dx
            new_y = y + dy
            if 0 <= new_x < n and 0 <= new_y < m:
                if new_x == tx and new_y == ty:
                    return "yes"
                if not visited[new_x][new_y] and grid[new_x][new_y] == 'F':
                    visited[new_x][new_y] = True
                    queue.append((new_x, new_y))

    return "no"

