def multiply_sparse_matrices(A, B):
    # Convert A to a dictionary of lists for efficient access
    A_dict = {}
    for i, row in enumerate(A):
        A_dict[i] = [(j, val) for j, val in enumerate(row) if val != 0]

    # Convert B to a dictionary of dictionaries for efficient access
    B_dict = {}
    for j, row in enumerate(B):
        B_dict[j] = {}
        for k, val in enumerate(row):
            if val != 0:
                B_dict[j][k] = val

    # Compute the result matrix
    result = []
    for i in range(len(A)):
        row = []
        for k in A_dict[i]:
            j = k
            val = A_dict[i][k]
            if j in B_dict:
                for l in B_dict[j]:
                    row.append(val * B_dict[j][l])
        # Remove any zero elements from the row
        row = [x for x in row if x != 0]
        result.append(row)

    return result

