def schedule_conference(input_str: str) -> list:
    sessions = []
    for line in input_str.split('\n'):
        if not line.strip():
            continue
        parts = line.split()
        if not parts:
            continue
        if parts[0] == 'n':
            n = int(parts[0])
            sessions.append(n)
        elif parts[0] == 'm':
            m = int(parts[0])
            sessions.append(m)
        else:
            start = int(parts[0])
            end = int(parts[1])
            sessions.append((start, end))

    result = []
    for n in sessions:
        if n == 0:
            result.append(0)
            continue
        sessions_sorted = sorted(sessions, key=lambda x: x[1])
        count = 0
        last_end = -1
        for s in sessions_sorted:
            if s[0] >= last_end:
                count += 1
                last_end = s[1]
        result.append(count)
    return result

