class NALUnitBuffer:
    def __init__(self):
        self.nal_units = []
        self.dependencies = {}

    def add_nal_unit(self, nal_unit):
        self.nal_units.append(nal_unit)

        if nal_unit.dependency_type is not None:
            if nal_unit.dependency_type == 'temporal':
                # Collect all NAL units with lower temporal layers
                for nu in self.nal_units:
                    if nu.temporal_layer < nal_unit.temporal_layer:
                        nal_unit.dependencies.append(nu)
            elif nal_unit.dependency_type == 'spatial':
                # Collect all NAL units with same temporal layer and lower packet_type
                for nu in self.nal_units:
                    if nu.temporal_layer == nal_unit.temporal_layer and nu.packet_type < nal_unit.packet_type:
                        nal_unit.dependencies.append(nu)

            # Check if all dependencies are present
            for dep in nal_unit.dependencies:
                if dep not in self.nal_units:
                    return False

        return True

    def decode_nal_unit(self, nal_unit):
        if nal_unit not in self.nal_units:
            return False
        for dep in nal_unit.dependencies:
            if dep not in self.nal_units:
                return False
        return True

