def largest_clique(matrix):
    n = len(matrix)
    if n == 0:
        return 0
    max_size = 1
    for i in range(n):
        current = [i]
        for j in range(i + 1, n):
            if matrix[i][j] == 1:
                new_current = current + [j]
                if len(new_current) > max_size:
                    max_size = len(new_current)
                # Check if all pairs in new_current are connected
                valid = True
                for a in new_current:
                    for b in new_current:
                        if a != b and matrix[a][b] != 1:
                            valid = False
                            break
                    if not valid:
                        break
                if valid:
                    max_size = len(new_current)
    return max_size

