from typing import List, Tuple

def minimum_travel_time(n: int, m: int, routes: List[Tuple[int, int, int]], queries: List[Tuple[int, int]]) -> List[int]:
    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v, w in routes:
        adj[u].append((v, w))
        adj[v].append((u, w))

    results = []
    for a, b in queries:
        if a == b:
            results.append(0)
            continue
        # Initialize distances
        INF = float('inf')
        dist = [INF] * (n + 1)
        dist[a] = 0
        heap = []
        heapq.heappush(heap, (0, a))

        while heap:
            current_dist, u = heapq.heappop(heap)
            if current_dist > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))

        if dist[b] == INF:
            results.append(-1)
        else:
            results.append(dist[b])

    return results

