def longest_common_ones(n: int, s1: str, s2: str) -> int:
    m = len(s1)
    p = len(s2)
    dp = [[0] * (p + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, p + 1):
            if s1[i-1] == '1' and s2[j-1] == '1':
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[m][p]

