from collections import deque, defaultdict

def earliest_time_to_be_virus_free(n: int, m: int, edges: list[tuple[int, int]], k: int, starting_devices: list[int]) -> int:
    # Build adjacency list
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Initialize BFS
    visited = [False] * (n + 1)
    queue = deque()
    for s in starting_devices:
        if not visited[s]:
            visited[s] = True
            queue.append((s, 0))

    max_time = 0
    while queue:
        u, t = queue.popleft()
        if t > max_time:
            max_time = t
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                queue.append((v, t + 1))

    # Check if all devices are visited
    for i in range(1, n + 1):
        if not visited[i]:
            return -1
    return max_time

