def topological_sort(graph):
    """
    Perform topological sorting on a Directed Acyclic Graph (DAG) using DFS.

    Args:
    graph (dict): A dictionary representing an adjacency list of the DAG.

    Returns:
    list: A list of vertices in topological order.
    """
    visited = set()
    stack = []

    def dfs(node):
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                dfs(neighbor)
        stack.append(node)

    for node in graph:
        if node not in visited:
            dfs(node)

    return stack[::-1]

