def is_tree(n: int, edges: list[tuple[int, int]]) -> bool:
    if n == 0:
        return False
    if n == 1:
        return len(edges) == 0
    if len(edges) != n - 1:
        return False

    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]  # Path compression
            u = parent[u]
        return u

    for a, b in edges:
        root_a = find(a)
        root_b = find(b)
        if root_a == root_b:
            return False
        parent[root_a] = root_b

    return True

