def findZeroSumSubarray(nums: List[int]) -> List[int]:
    prefix_sums = {0: -1}
    current_sum = 0
    for i, num in enumerate(nums):
        current_sum += num
        if current_sum in prefix_sums:
            start = prefix_sums[current_sum] + 1
            end = i
            return nums[start:end+1]
        prefix_sums[current_sum] = i
    return []

