def can_always_ensure_route(T, test_cases):
    results = []
    for case in test_cases:
        n, k, s, t = case
        if s == t:
            results.append("Yes")
            continue
        if k == 0:
            results.append("Yes")
            continue
        # Build adjacency list
        adj = [[] for _ in range(n + 1)]
        for u in range(1, n + 1):
            for v in range(1, n + 1):
                if u != v:
                    adj[u].append(v)
        # Perform BFS
        visited = [False] * (n + 1)
        queue = deque()
        queue.append(s)
        visited[s] = True
        found = False
        while queue:
            u = queue.popleft()
            if u == t:
                found = True
                break
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        results.append("Yes" if found else "No")
    return results

