def organize_indexes(indexes: str) -> str:
    if not indexes:
        return ""
    nums = list(map(int, indexes.split(',')))
    result = []
    start = nums[0]
    for num in nums[1:]:
        if num == start + 1:
            start = num
        else:
            if start == num:
                result.append(str(start))
            else:
                result.append(f"{start}-{num}")
            start = num
    # Add the last range or number
    if start == nums[-1]:
        result.append(str(start))
    else:
        result.append(f"{start}-{nums[-1]}")
    return ','.join(result)

